import React from 'react';

import { addFundAsync, updateFundAsync } from '@apps/Finances/@services/funds.service';
import { IFund } from '@apps/Finances/@types/funds.types';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

interface IFundEditProps {
  fund: IFund;
  onSave: (up: IFund) => void;
}

const FundEdit: React.FC<IFundEditProps> = ({ fund, onSave }) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IFund>(fund);

  const handleChange =
    <k extends keyof IFund>(fieldName: k) =>
    (value: IFund[k]) =>
      setData((cur) => ({ ...cur, [fieldName]: value }));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setIsLoading(true);

      if (data.id === 0) {
        const up = await addFundAsync(data);
        onSave(up);
      } else {
        const up = await updateFundAsync(data);
        onSave(up);
      }
    } catch (error) {
      setErr(error as Error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="vertical-gapped">
      <PohInput
        label="Название"
        required
        name="fund_name"
        autoComplete="fund_name"
        horizontal
        value={data.name}
        onChange={handleChange('name')}
        maxLength={128}
        disabled={isLoading}
      />
      <PohInput
        label="Описание"
        type={InputTypes.textarea}
        name="fund_description"
        autoComplete="fund_description"
        horizontal
        value={data.description}
        onChange={handleChange('description')}
        disabled={isLoading}
      />
      <PohRow>
        <PohCol sm={2}></PohCol>
        <PohCol sm={5}>
          <PohCheckbox
            label="Активен"
            checked={data.is_active}
            onChange={handleChange('is_active')}
          />
        </PohCol>
        <PohCol sm={5}>
          <PohCheckbox
            label="Публичен"
            checked={data.is_public}
            onChange={handleChange('is_public')}
          />
        </PohCol>
      </PohRow>
      {err && <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>}
      <PohRow>
        <PohCol sm={2} />
        <PohCol sm={10}>
          <PohButton type="submit" disabled={isLoading}>
            Сохранить
          </PohButton>
        </PohCol>
      </PohRow>
    </form>
  );
};

export const editFundInModalAsync = (fund: IFund): Promise<IFund> => {
  return new Promise((res) => {
    showModal({
      title: fund.id > 0 ? 'Редактирование фонда' : 'Создание фонда',
      children: (clos) => (
        <FundEdit
          fund={fund}
          onSave={(up) => {
            res(up);
            clos();
          }}
        />
      ),
    });
  });
};
